using System.ComponentModel;
using System.Text.Json;
using System.Text.Json.Nodes;
using ModelContextProtocol.Protocol;
using ModelContextProtocol.Server;
namespace PowerShapeMcp;
[McpServerToolType]
public sealed class CurveScaleTools(BridgeSession session) {
 [McpServerTool(Name="prepare_owned_curve_scale",ReadOnly=false,Destructive=false,Idempotent=false,OpenWorld=false)]
 [Description("Prepare one experimental uniform scale of an explicit COMPCURVE beside one unchanged SOLID in an owned mm/WORLD/idle/empty-selection copy. Positive factor0.01..100 except1 and bounded explicit WORLD centre come from prepare_uniform_scale_plan. Captures complete1..N controls, both tangent directions/magnitudes/free flags and pinned neighboring SOLID witnesses. No CAD mutation, selection or save. Separate execution and verification required; full only and default-off flag.")]
 public Task<CallToolResult> Prepare([Description("Passive scalePlanHandle for the exact one-COMPCURVE set and explicit factor/centre.")]string scalePlanHandle,[Description("Fresh binding for this owned working copy.")]string workingDocumentBindingHandle,[Description("Exact complete startIndex1,endIndexN,N2..32; independently checked against POINT.NUMBER.")]JsonElement curveRange,CancellationToken cancellationToken)=>new SolidScaleTools(session,false,true).Run("prepare_owned_curve_scale",new(){["scalePlanHandle"]=scalePlanHandle,["workingDocumentBindingHandle"]=workingDocumentBindingHandle,["curveRange"]=JsonNode.Parse(curveRange.GetRawText())},cancellationToken);
 [McpServerTool(Name="execute_owned_curve_scale",ReadOnly=false,Destructive=true,Idempotent=false,OpenWorld=false)]
 [Description("Execute the prepared one-COMPCURVE uniform NOKEEP scale once through the existing fixed13phase program and one-use claim/fence/journal. Selects only this curve and clears selection only after all successful phases. Remains fenced until separate verification. No save/OPEN/activation/mouse. Unknown stops with no automatic CANCEL/DISMISS/clear/inverse/replay. Control/sample proof only, not full topology. Full only.")]
 public Task<CallToolResult> Execute([Description("Unconsumed ownedCurveScaleHandle from prepare_owned_curve_scale in this connection.")]string ownedCurveScaleHandle,CancellationToken cancellationToken)=>new SolidScaleTools(session,false,true).Run("execute_owned_curve_scale",new(){["ownedSolidScaleHandle"]=ownedCurveScaleHandle},cancellationToken);
 [McpServerTool(Name="verify_owned_curve_scale",ReadOnly=false,Destructive=false,Idempotent=false,OpenWorld=false)]
 [Description("Independently verify the original complete13phase COMPCURVE scale with fresh context. Checks affine control positions, unchanged tangent directions, scaled magnitudes/length, squared raw area, scaled observed ranges and exact free flags/neighbor SOLID/ownership/files/windows. May complete original journal and release only matching fence. No CAD command or retry. Control/sample behavior, not topology or saved persistence. Full only.")]
 public Task<CallToolResult> Verify([Description("Original Native execution request ID.")]string executionRequestId,[Description("Exact original immutable raw execution SHA256.")]string executionReceiptSha256,[Description("Fresh post-return candidate document handle.")]string candidateDocumentHandle,[Description("Fresh one-use active document listing handle.")]string activeDocumentHandle,CancellationToken cancellationToken)=>new SolidScaleTools(session,false,true).Run("verify_owned_curve_scale",new(){["executionRequestId"]=executionRequestId,["executionReceiptSha256"]=executionReceiptSha256,["candidateDocumentHandle"]=candidateDocumentHandle,["activeDocumentHandle"]=activeDocumentHandle},cancellationToken);
 public static McpServerTool[] Create(BridgeSession s){if(!s.PreparedEnabled("prepare_owned_curve_scale"))return[];var t=new CurveScaleTools(s);var prepare=SolidQuarterTurnTools.Schema("scalePlanHandle","workingDocumentBindingHandle");prepare["properties"]!["curveRange"]=new JsonObject{["type"]="object",["description"]="Complete explicit1..N controls, N2..32; checked against native POINT.NUMBER.",["properties"]=new JsonObject{["startIndex"]=new JsonObject{["type"]="integer",["const"]=1},["endIndex"]=new JsonObject{["type"]="integer",["minimum"]=2,["maximum"]=32}},["required"]=new JsonArray("startIndex","endIndex"),["additionalProperties"]=false};prepare["required"]!.AsArray().Add("curveRange");return[new StrictTool(McpServerTool.Create(t.Prepare),s,prepare,x=>CurveTranslationProof.Range(x["curveRange"]!.AsObject())),new StrictTool(McpServerTool.Create(t.Execute),s,SolidQuarterTurnTools.Schema("ownedCurveScaleHandle")),new StrictTool(McpServerTool.Create(t.Verify),s,SolidQuarterTurnTools.Schema("executionRequestId","executionReceiptSha256","candidateDocumentHandle","activeDocumentHandle"))];}
}
